  var totalCols = header.length;

  var out = rows.map(function (r) {
    var row = r._raw.slice();              // all original columns (dynamic count)
    row.push(
      r.nTimestamp,
      r.nJoined,
      r.nPhone,
      r.nPark,
      r.flag,
      r.flagNotes.join("; "),
      r.mergedFrom.join(", "),
      // deduplicate field names in case multiple donors filled the same field
      uniqueArray(r.mergedFields).join(", ")
    );
    return row;
  });

  if (out.length > 0) {
    sheet.getRange(2, 1, out.length, totalCols).setValues(out);
  }

  // Formatting
  sheet.setFrozenRows(1);
  sheet.getRange(1, 1, 1, totalCols).setFontWeight("bold");
  sheet.autoResizeColumns(1, totalCols);

  // Colour-code Flag column
  var flagColIndex = colCount + 5;         // 1-based index within the row
  var flagRange = sheet.getRange(2, flagColIndex, out.length, 1);
  var flagVals  = flagRange.getValues();
  for (var i = 0; i < flagVals.length; i++) {
    var color;
    if (flagVals[i][0] === "SUPERSEDED") color = "#f4cccc";
    else if (flagVals[i][0] === "REVIEW") color = "#fff2cc";
    else                                  color = "#d9ead3";
    sheet.getRange(i + 2, 1, 1, totalCols).setBackground(color);
  }
}

function uniqueArray(arr) {
  var seen = {};
  return arr.filter(function (item) {
    if (seen[item]) return false;
    seen[item] = true;
    return true;
  });
}
