  var out = rows.map(function (r) {
    // Build MergedFrom: kept row's own number first, then donors
    var mergedFromStr = "";
    if (r.mergedFrom.length > 0) {
      mergedFromStr = [r._srcRow].concat(r.mergedFrom).join(", ");
    }

    var row = r._raw.slice();
    row.push(
