  if (!rawSheet) throw new Error("Sheet '" + CONFIG.RAW_SHEET + "' not found");
  const rawData = rawSheet.getDataRange().getValues();
  const rawHeaders = rawData.shift();
  const colCount = rawHeaders.length;

  // Build a map: normalised header text → column index
  var colIdx = {};
  rawHeaders.forEach(function (h, i) {
    colIdx[String(h).replace(/[\s_\-]/g, "").toLowerCase()] = i;
  });

  function requireCol(key) {
    if (colIdx[key] === undefined)
      throw new Error("Cannot find a column matching '" + key +
        "' in Raw headers: " + rawHeaders.join(", "));
    return colIdx[key];
  }

  var CI = {
    ts:    requireCol(KNOWN_COLS.TIMESTAMP),
    name:  requireCol(KNOWN_COLS.NAME),
    email: requireCol(KNOWN_COLS.EMAIL),
    joined: requireCol(KNOWN_COLS.JOINED_BEFORE),
    phone: requireCol(KNOWN_COLS.PHONE),
    park:  requireCol(KNOWN_COLS.PREFERRED_PARK),
  };

  var parkMap = buildParkMap(ss);

  // --- Normalize every row ---
  var rows = rawData.map(function (r, i) {
    return {
      _srcRow:        i + 2,
      _raw:           r.slice(),
      name:           String(r[CI.name]).trim(),
      email:          String(r[CI.email]).trim().toLowerCase(),
      nTimestamp:     normalizeTimestamp(r[CI.ts]),
      nJoined:       normalizeYesNo(r[CI.joined]),
      nPhone:        normalizePhone(r[CI.phone]),
      nPark:         normalizePark(r[CI.park], parkMap),
      flag:          "OK",
      flagNotes:     [],
      mergedFrom:    [],
      mergedFields:  [],
      supersededBy:  "",
    };
  });

  // --- Flag cells that need review ---
  rows.forEach(function (r) {
    if (r.nJoined   === "REVIEW") r.flagNotes.push("YN");
    if (r.nPhone    === "REVIEW") r.flagNotes.push("Phone");
    if (r.nTimestamp === "REVIEW") r.flagNotes.push("Timestamp");
    if (r.nPark     === "REVIEW") r.flagNotes.push("Park");
    if (r.email     === "")       r.flagNotes.push("NoEmail");
  });

  // --- Deduplicate by email (keep latest) ---
  dedupeByEmail(rows);

  // --- Deduplicate by name+timestamp proximity (merge) ---
  dedupeByNameTime(rows, CI);

  // --- Finalise flag column ---
  rows.forEach(function (r) {
    if (r.flag === "SUPERSEDED") return;
    r.flag = r.flagNotes.length > 0 ? "REVIEW" : "OK";
  });

  // --- Write Clean sheet ---
  writeCleanSheet(ss, rows, rawHeaders, colCount);

  SpreadsheetApp.getUi().alert(
    "Done — " + rows.length + " rows processed. Check the '" +
    CONFIG.CLEAN_SHEET + "' sheet.");
}

// ── Normalizers ─────────────────────────────────────────────────────────────

function normalizeYesNo(val) {
  var s = String(val).trim().toLowerCase();
  if (/^y(es)?$/.test(s)) return "Yes";
  if (/^no?$/.test(s))    return "No";
  if (s === "")            return "";
  return "REVIEW";
}

function normalizePhone(val) {
  var digits = String(val).replace(/\D/g, "");
  if (digits.length === 11 && digits[0] === "1") digits = digits.slice(1);
  if (digits.length === 7 && CONFIG.DEFAULT_AREA_CODE) {
    digits = CONFIG.DEFAULT_AREA_CODE + digits;
  }
  if (digits.length === 10) return digits;
  if (digits === "") return "";
  return "REVIEW";
}

function normalizeTimestamp(val) {
  if (val instanceof Date && !isNaN(val)) return val;
  var d = new Date(val);
  if (!isNaN(d)) return d;
  return "REVIEW";
}

function normalizePark(val, parkMap) {
  var s = String(val).trim();
  if (s === "") return "";
  var key = s.replace(/[^a-zA-Z]/g, "").toLowerCase();
  if (parkMap.hasOwnProperty(key)) return parkMap[key];
  return "REVIEW";
}

function buildParkMap(ss) {
  var sheet = ss.getSheetByName(CONFIG.MAP_SHEET);
  if (!sheet) throw new Error("Sheet '" + CONFIG.MAP_SHEET + "' not found");
  var data = sheet.getDataRange().getValues();
  var map = {};
  data.forEach(function (r) {
    var key = String(r[0]).replace(/[^a-zA-Z]/g, "").toLowerCase();
    if (key) map[key] = String(r[1]).trim();
  });
  return map;
}

// ── Deduplication ───────────────────────────────────────────────────────────

function dedupeByEmail(rows) {
  var groups = {};
  rows.forEach(function (r, i) {
    if (!r.email) return;
    if (!groups[r.email]) groups[r.email] = [];
    groups[r.email].push(i);
  });

  Object.keys(groups).forEach(function (email) {
    var idxs = groups[email];
    if (idxs.length < 2) return;

    var bestIdx = idxs[0];
    var bestTime = -Infinity;
    idxs.forEach(function (i) {
      var ms = tsMs(rows[i].nTimestamp);
      if (ms > bestTime) { bestTime = ms; bestIdx = i; }
    });

    idxs.forEach(function (i) {
      if (i !== bestIdx) {
        rows[i].flag = "SUPERSEDED";
        rows[i].flagNotes = ["DupEmail"];
        rows[i].supersededBy = rows[bestIdx]._srcRow;
      }
    });
    rows[bestIdx].flagNotes.push("DupEmail-kept");
  });
}

function dedupeByNameTime(rows, CI) {
  var windowMs = CONFIG.DUP_WINDOW_MINUTES * 60 * 1000;

  var groups = {};
  rows.forEach(function (r, i) {
    if (r.flag === "SUPERSEDED") return;
    var nk = nameKey(r.name);
    if (!nk) return;
    if (!groups[nk]) groups[nk] = [];
    groups[nk].push(i);
  });

  Object.keys(groups).forEach(function (nk) {
    var idxs = groups[nk];
    if (idxs.length < 2) return;

    idxs.sort(function (a, b) {
      return tsMs(rows[a].nTimestamp) - tsMs(rows[b].nTimestamp);
    });

    var used = {};
    for (var i = 0; i < idxs.length; i++) {
      if (used[idxs[i]]) continue;
      var cluster = [idxs[i]];
      var baseMs = tsMs(rows[idxs[i]].nTimestamp);
      if (baseMs === -1) continue;

      for (var j = i + 1; j < idxs.length; j++) {
        if (used[idxs[j]]) continue;
        var cmp = tsMs(rows[idxs[j]].nTimestamp);
        if (cmp === -1) continue;
        if (cmp - baseMs <= windowMs) {
          cluster.push(idxs[j]);
        }
      }
      if (cluster.length < 2) continue;

      var keepIdx = cluster[cluster.length - 1];
      var keep = rows[keepIdx];
      for (var k = 0; k < cluster.length - 1; k++) {
        var donor = rows[cluster[k]];
        var filled = mergeRow(keep, donor, CI);
        if (filled.length > 0) {
          keep.mergedFields = keep.mergedFields.concat(filled);
        }
        keep.mergedFrom.push(donor._srcRow);
        donor.flag = "SUPERSEDED";
        donor.flagNotes = ["DupNameTime"];
        donor.supersededBy = keep._srcRow;
        used[cluster[k]] = true;
      }
      keep.flagNotes.push("DupNameTime-merged");
    }
  });
}

function mergeRow(target, donor, CI) {
  var filled = [];

  if (!target.email && donor.email) {
    target.email = donor.email;
    target._raw[CI.email] = donor._raw[CI.email];
    filled.push("Email");
  }
  if ((!target.nJoined || target.nJoined === "REVIEW") &&
      donor.nJoined && donor.nJoined !== "REVIEW") {
    target.nJoined = donor.nJoined;
    target._raw[CI.joined] = donor._raw[CI.joined];
    filled.push("JoinedBefore");
  }
  if ((!target.nPhone || target.nPhone === "REVIEW") &&
      donor.nPhone && donor.nPhone !== "REVIEW") {
    target.nPhone = donor.nPhone;
    target._raw[CI.phone] = donor._raw[CI.phone];
    filled.push("Phone");
  }
  if ((!target.nPark || target.nPark === "REVIEW") &&
      donor.nPark && donor.nPark !== "REVIEW") {
    target.nPark = donor.nPark;
    target._raw[CI.park] = donor._raw[CI.park];
    filled.push("PreferredPark");
  }
  if (target.nTimestamp === "REVIEW" && donor.nTimestamp instanceof Date) {
    target.nTimestamp = donor.nTimestamp;
    target._raw[CI.ts] = donor._raw[CI.ts];
    filled.push("Timestamp");
  }

  return filled;
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function nameKey(name) {
  return String(name).replace(/[^a-zA-Z]/g, "").toLowerCase();
}

function tsMs(ts) {
  return (ts instanceof Date) ? ts.getTime() : -1;
}

// ── Output ──────────────────────────────────────────────────────────────────

function writeCleanSheet(ss, rows, rawHeaders, colCount) {
  var sheet = ss.getSheetByName(CONFIG.CLEAN_SHEET);
  if (sheet) {
    sheet.clear();
  } else {
    sheet = ss.insertSheet(CONFIG.CLEAN_SHEET);
  }

  var cleanCols = [
    "Clean_Timestamp", "Clean_Joined", "Clean_Phone", "Clean_Park",
    "Flag", "SupersededBy", "FlagNotes", "MergedFrom", "MergedFields"
  ];
