    row.push(
      r.nTimestamp,
      r.nJoined,
      r.nPhone,
      r.nPark,
      r.flag,
      r.supersededBy !== "" ? r.supersededBy : "",
      r.flagNotes.join("; "),
      mergedFromStr,
      uniqueArray(r.mergedFields).join(", ")
    );
